WITH patient_durations AS (SELECT pharmacy.poe_id, (pharmacy.stoptime - pharmacy.starttime) AS duration FROM pharmacy JOIN prescriptions ON pharmacy.poe_id = prescriptions.poe_id WHERE prescriptions.drug = 'DAPT' AND prescriptions.starttime IS NOT NULL AND prescriptions.stoptime IS NOT NULL AND EXTRACT(YEAR FROM pharmacy.starttime) = 2017 AND EXTRACT(YEAR FROM pharmacy.stoptime) = 2017) SELECT percentile_cont(0.75) within GROUP (ORDER BY duration) - percentile_cont(0.25) within GROUP (ORDER BY duration) AS interquartile_range FROM patient_durations WHERE pharmacy.subject_id = 757071 AND pharmacy.hadm_id = 757071;